-- Link screen names within detailed guide introductions without duplicating instructions.
with target(slug,label,href) as (values ('bookings-dashboard','Dashboard','/bookings'),('bookings-rate-model','Rates','/bookings/rates/card'),('bookings-new-request','Requests','/bookings/requests'),('bookings-asset-inventory','Assets','/bookings/rates/assets'),('bookings-requests','Requests','/bookings/requests'),('bookings-term-report','Term report','/bookings/report'),('bookings-partners','Partners','/bookings/partners'),('bookings-calendar','Calendar','/bookings/calendar'),('log-read-a-clock','Open clock','/log/programs'),('log-dad-log','DAD log','/log/dad-log'),('log-schedule-a-program','Schedule','/log/programs'),('log-underwriting-hours','Schedule','/log/programs')), match as (select a.id,t.slug,t.href, (ord-1)::text idx, node from public.rc_articles a join target t on t.slug=a.slug cross join lateral jsonb_array_elements(a.body->'content'->0->'content') with ordinality x(node,ord) where a.kind='guide' and a.edited_since_release=false and btrim(lower(node->>'text'))=lower(t.label) and not exists(select 1 from jsonb_array_elements(coalesce(node->'marks','[]'::jsonb)) m where m->>'type'='link')), chosen as (select distinct on(id) * from match order by id,idx::int) update public.rc_articles a set body=jsonb_set(a.body,array['content','0','content',c.idx,'marks'],coalesce(c.node->'marks','[]'::jsonb) || jsonb_build_array(jsonb_build_object('type','link','attrs',jsonb_build_object('href',c.href))),true),version_note='Contextual hyperlink on the relevant screen name; instructions preserved' from chosen c where a.id=c.id returning a.slug,a.version;
